function showSection(name, navEl) {
  const normalized = normalizeAdminSection(name);
  name = normalized.section || name;
  mountUnifiedSystemSettings();
  if (name === 'indicator-smart' && !isAdminFeatureEnabled('core_indicators')) {
    showToast('核心指标当前已封存');
    name = 'overview';
    navEl = document.querySelector('.admin-nav-item[data-section="overview"]');
  }
  if (name.indexOf('knowledge-') === 0 && !isAdminFeatureEnabled('knowledge')) {
    showToast('知识专区当前暂不开放');
    name = 'overview';
    navEl = document.querySelector('.admin-nav-item[data-section="overview"]');
  }
  if (name === 'forecast-model' && !isAdminFeatureEnabled('stock_forecast')) {
    showToast('预测功能当前未开放');
    return;
  }
  document.querySelectorAll('[id^="section-"]').forEach(s => s.style.display = 'none');
  document.getElementById('section-' + name).style.display = 'block';
  setActiveAdminNav(navEl || document.querySelector(`.admin-nav-item[data-section="${name}"]`));
  document.getElementById('page-title').textContent = sectionTitles[name];
  if (name === 'users') {
    loadAdminUsers();
  }
  if (name === 'segments') {
    loadAdminUserSegments(false);
  }
  if (name === 'points') {
    loadAdminPoints(false);
  }
  if (name.startsWith('indicator-')) {
    refreshAdminIndicatorHub(false).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'access') {
    renderAccessAudit();
  }
  if (name === 'settings-features' || name.startsWith('settings-')) {
    loadSiteConfig().catch((error) => showToast(error.message || '配置加载失败'));
  }
  if (name === 'agent-workflows') {
    loadAdminAgentWorkflows().catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'hermes') {
    loadSiteConfig().catch((error) => showToast(error.message || '配置加载失败'));
    loadAdminHermesMemorySummary(false).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'commission') {
    loadAdminCommission().catch((error) => showToast(error.message || '收益数据加载失败'));
  }
  if (name === 'channels') {
    loadAdminChannels().catch((error) => showToast(error.message || '渠道数据加载失败'));
  }
  if (name === 'news-sources') {
    loadAdminNewsSources(false).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'forecast-model') {
    initForecastEditorEvents();
    loadAdminForecastModel().catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'task-center') {
    refreshAdminTaskCenter(false).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'settings-features') {
    const url = new URL(window.location.href);
    const queryPanel = String(url.searchParams.get('settings_panel') || '').trim();
    const initialPanel = normalized.panel || queryPanel || 'theme';
    window.requestAnimationFrame(() => {
      openAdminSettingsSubmenu(initialPanel, { updateQuery: true });
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }
  if (name === 'knowledge-overview') {
    loadAdminKnowledgeAssets(false).then(() => {
      renderAdminKnowledgeOverview();
    }).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'knowledge-intake') {
    loadAdminKnowledgeItems(false).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'knowledge-encyclopedia') {
    Promise.all([
      loadAdminKnowledgeItems(false),
      loadAdminKnowledgeAssets(false),
    ]).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'knowledge-entries') {
    Promise.all([
      loadAdminKnowledgeItems(false),
      loadAdminKnowledgeAssets(false),
    ]).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'knowledge-graph') {
    Promise.all([
      loadAdminKnowledgeItems(false),
      loadAdminKnowledgeMap(false),
    ]).catch((error) => showToast(error.message || '加载失败'));
  }
  if (name === 'token-usage') {
    refreshAdminTokenUsage(false).catch((error) => showToast(error.message || '加载失败'));
  }
  updateAdminQuery(name);
}

function showHermesSubsection(tab, navEl) {
  const allowed = new Set(['overview', 'usage', 'compute', 'memory', 'config', 'audit']);
  const nextTab = allowed.has(String(tab || '').trim()) ? String(tab).trim() : 'overview';
  const labels = {overview: '总览', usage: '调用统计', compute: '算力与排行', memory: '记忆治理', config: '能力配置', audit: '拦截审计'};
  const section = document.getElementById('section-hermes');
  if (!section || section.style.display === 'none') {
    showSection('hermes', navEl || document.querySelector(`[data-section="hermes"][data-hermes-subsection="${nextTab}"]`));
  } else if (navEl) {
    setActiveAdminNav(navEl);
  }
  document.querySelectorAll('[data-hermes-pane]').forEach((pane) => {
    pane.style.display = pane.dataset.hermesPane === nextTab ? '' : 'none';
  });
  document.querySelectorAll('[data-hermes-tab]').forEach((button) => {
    button.classList.toggle('active', button.dataset.hermesTab === nextTab);
  });
  const pageTitle = document.getElementById('page-title');
  if (pageTitle) pageTitle.textContent = `Hermes · ${labels[nextTab]}`;
  const activeNav = document.querySelector(`[data-section="hermes"][data-hermes-subsection="${nextTab}"]`);
  if (activeNav) setActiveAdminNav(activeNav);
  if (nextTab === 'audit') {
    loadAdminHermesInterceptionAudits(false).catch((error) => showToast(error.message || '审计加载失败'));
  }
  const url = new URL(window.location.href);
  url.searchParams.set('section', 'hermes');
  url.searchParams.set('hermes_tab', nextTab);
  window.history.replaceState({}, '', url);
}

function showAnalyticsSection(section) {
  if (section === 'segment' && !isAdminFeatureEnabled('vip')) {
    showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
    return;
  }
  if (!isAdminFeatureEnabled('analytics_module')) {
    showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
    return;
  }
  document.querySelectorAll('[id^="section-"]').forEach(s => s.style.display = 'none');
  document.getElementById('section-analytics').style.display = 'block';
  const navEl = document.getElementById('nav-' + section);
  setActiveAdminNav(navEl);
  document.querySelectorAll('[id^="admin-nav-"]').forEach((item) => item.classList.toggle('active', item.id === `admin-nav-${section}`));
  document.getElementById('page-title').textContent = analyticsTitles[section] || sectionTitles.analytics;
  window.dashboardDefaultSection = section;
  if (window.initDashboardCharts) {
    window.initDashboardCharts(section);
  }
  updateAdminQuery(section);
}
function showToast(msg) {
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#1A2E45;border:1px solid rgba(200,169,110,0.3);color:#C8A96E;padding:12px 20px;border-radius:8px;font-size:13px;z-index:9999;transition:opacity 0.3s';
  t.textContent = msg || '操作成功';
  document.body.appendChild(t);
  setTimeout(() => { t.style.opacity='0'; setTimeout(() => t.remove(), 300); }, 2000);
}

