function getAdminKnowledgeMapNodeRelations(nodeId) {
  const payload = adminKnowledgeMapState.payload || {};
  const nodes = Array.isArray(payload.nodes) ? payload.nodes : [];
  const edges = Array.isArray(payload.edges) ? payload.edges : [];
  const nodeMap = new Map(nodes.map((node) => [node.id, node]));
  const parents = [];
  const children = [];
  edges.forEach((edge) => {
    if (edge.to === nodeId && nodeMap.has(edge.from)) parents.push(nodeMap.get(edge.from));
    if (edge.from === nodeId && nodeMap.has(edge.to)) children.push(nodeMap.get(edge.to));
  });
  return {
    parents: parents.filter(Boolean).slice(0, 8),
    children: children.filter(Boolean).slice(0, 8),
  };
}

function centerAdminKnowledgeMapNode(nodeId, positions) {
  const shell = document.querySelector('.admin-kg-board-shell');
  const point = positions && positions[nodeId];
  if (!shell || !point) return;
  shell.scrollTo({
    left: Math.max(0, Math.round(point.x - shell.clientWidth / 2)),
    top: Math.max(0, Math.round(point.y - shell.clientHeight / 2)),
    behavior: 'smooth',
  });
}

function getAdminKnowledgeMapFilteredPayload() {
  const payload = adminKnowledgeMapState.payload || {};
  const allNodes = Array.isArray(payload.nodes) ? payload.nodes : [];
  const allEdges = Array.isArray(payload.edges) ? payload.edges : [];
  const depth = Math.max(2, Math.min(Number(payload.max_depth || 5), Number(adminKnowledgeMapState.depth || payload.default_depth || 3)));
  const type = adminKnowledgeMapState.type || 'all';
  const query = String(adminKnowledgeMapState.query || '').trim().toLowerCase();
  const depthNodes = allNodes.filter((node) => Number(node.level || 99) <= depth);
  const visibleIds = new Set();
  depthNodes.forEach((node) => {
    if (node.kind !== 'root' && type !== 'all' && node.kind !== type) return;
    const haystack = [
      node.label,
      node.full_label,
      node.summary,
      Array.isArray(node.keywords) ? node.keywords.join(' ') : '',
    ].join(' ').toLowerCase();
    if (query && !haystack.includes(query)) return;
    visibleIds.add(node.id);
  });
  const rootNode = depthNodes.find((node) => node.kind === 'root');
  if (rootNode) visibleIds.add(rootNode.id);
  if (query) {
    allEdges.forEach((edge) => {
      if (visibleIds.has(edge.from) || visibleIds.has(edge.to)) {
        visibleIds.add(edge.from);
        visibleIds.add(edge.to);
      }
    });
  } else if (type !== 'all') {
    allEdges.forEach((edge) => {
      if (visibleIds.has(edge.to)) visibleIds.add(edge.from);
    });
  } else {
    depthNodes.forEach((node) => visibleIds.add(node.id));
  }
  return {
    payload,
    depth,
    nodes: depthNodes.filter((node) => visibleIds.has(node.id)),
    edges: allEdges.filter((edge) => visibleIds.has(edge.from) && visibleIds.has(edge.to)),
  };
}

