async function runAdminTask(taskCode, forceRun) {
  const res = await fetch(`/api/admin/tasks/${encodeURIComponent(taskCode)}/run`, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({force: !!forceRun}),
  });
  const data = await res.json();
  if (!res.ok || !data.ok) {
    showToast((data && data.error) || '任务执行失败');
    return;
  }
  applyAdminTaskCenterPayload(data);
