async function toggleAdminIndicator(indicatorId, enabled) {
  const item = getAdminIndicatorItemById(indicatorId);
  const definition = getAdminIndicatorDefinition(indicatorId);
  const payloadSource = definition ? {
    indicator_code: definition.indicator_code,
    indicator_name: definition.indicator_name,
    category: definition.category,
    description: definition.description,
    unit: definition.unit,
    owner: definition.owner,
    source_type: definition.source_type,
    source_type_label: definition.source_type_label,
    provider: definition.provider,
    status_hint: definition.status_hint,
    assessment_template: definition.assessment_template,
    alert_template: definition.alert_template,
    watchers: definition.watchers || [],
    display_config: definition.display_config || {},
    enabled
  } : (item ? {
    indicator_code: item.id,
    indicator_name: item.name,
    category: item.category,
    description: item.assessment || '',
    unit: '',
    owner: item.owner,
    source_type: item.source_type,
    source_type_label: item.source_type_label,
    provider: item.provider,
    status_hint: item.status,
    assessment_template: item.assessment,
    alert_template: item.alert,
    watchers: item.watchers || [],
    display_config: {},
    enabled
  } : null);
  if (!payloadSource) {
    showToast('未找到指标');
    return;
  }
  const resp = await fetch('/api/admin/indicator-definitions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payloadSource),
  });
  const data = await resp.json();
  if (!resp.ok || !data.ok) {
    showToast('指标开关保存失败');
    return;
  }
  await refreshAdminIndicatorHub(false);
  showToast(`${payloadSource.indicator_name} 已切换为${enabled ? '启用' : '关闭'}`);
}

