function renderIndicatorSourcePreview(preview) {
  const emptyNode = document.getElementById('admin-indicator-source-preview-empty');
  const panelNode = document.getElementById('admin-indicator-source-preview');
  if (!preview) {
    if (emptyNode) emptyNode.style.display = 'block';
    if (panelNode) panelNode.style.display = 'none';
    return;
  }
  if (emptyNode) emptyNode.style.display = 'none';
  if (panelNode) panelNode.style.display = 'block';
  const titleNode = document.getElementById('indicator-source-preview-title');
  if (titleNode) titleNode.textContent = `${preview.source_code || '--'} -> ${preview.indicator_code || '--'}`;
  const metaNode = document.getElementById('indicator-source-preview-meta');
  if (metaNode) metaNode.textContent = `${preview.provider || '--'} · ${preview.method || '--'} · ${preview.endpoint || '--'}`;
  const valueNode = document.getElementById('indicator-source-preview-value-path');
  if (valueNode) valueNode.textContent = (preview.suggested_mapping && preview.suggested_mapping.value_path) || '--';
  const timeNode = document.getElementById('indicator-source-preview-time-path');
  if (timeNode) timeNode.textContent = (preview.suggested_mapping && preview.suggested_mapping.time_path) || '--';
  const statusNode = document.getElementById('indicator-source-preview-status-path');
  if (statusNode) statusNode.textContent = (preview.suggested_mapping && preview.suggested_mapping.status_path) || '--';
  const pathsNode = document.getElementById('indicator-source-preview-paths');
  if (pathsNode) {
    const paths = Array.isArray(preview.discovered_paths) ? preview.discovered_paths : [];
    pathsNode.innerHTML = paths.length
      ? paths.map((item) => `<span class="tag tag-blue">${escapeHtml(item)}</span>`).join('')
      : '<span style="font-size:12px;color:#8899aa">未发现字段路径</span>';
  }
  const blueprintNode = document.getElementById('indicator-source-preview-blueprint');
  if (blueprintNode) {
    const blueprint = preview.blueprint || {};
    const requestBlueprint = blueprint.request_blueprint || {};
    blueprintNode.innerHTML = [
      `连接器：${escapeHtml(preview.connector_type || '--')}`,
      `Extractor Type：${escapeHtml(blueprint.extractor_type || '--')}`,
      `Extractor Path：${escapeHtml(blueprint.extractor_path || '--')}`,
      `Expected Contains：${escapeHtml(blueprint.expected_contains || '--')}`,
      `API URL：${escapeHtml(requestBlueprint.api_url || '--')}`,
      `Notes：${escapeHtml(requestBlueprint.notes || '--')}`,
    ].map((line) => `<div>${line}</div>`).join('');
  }
  const testNode = document.getElementById('indicator-source-preview-test');
  if (testNode) {
    testNode.innerHTML = [
      `状态：${escapeHtml(preview.last_test_status || '--')}`,
      `详情：${escapeHtml(preview.last_test_detail || '--')}`,
    ].map((line) => `<div>${line}</div>`).join('');
  }
  const payloadNode = document.getElementById('indicator-source-preview-payload');
  if (payloadNode) payloadNode.textContent = preview.sample_payload_text || '{}';
}

