function buildTraceTimelineHtml(trace) {
  const timeline = Array.isArray(trace && trace.timeline) ? trace.timeline : [];
  if (!timeline.length) return '<div class="admin-modal-copy">暂无湖内追溯记录。</div>';
  return timeline.map((entry) => `
    <div class="admin-modal-history-row">
      <div class="admin-modal-history-date">${escapeHtml(entry.time || '--')}</div>
      <div class="admin-modal-history-text">${escapeHtml(entry.type || '--')} · ${escapeHtml(entry.summary || '--')}</div>
    </div>
  `).join('');
}

