}

async function backupAdminHermesMemory() {
  const tenantSlug = getAdminHermesMemorySelectedTenant();
  const rangeKey = document.getElementById('admin-hermes-memory-backup-range')?.value || '3m';
  if (!tenantSlug) {
    showToast('请先选择租户');
    return false;
  }
  setAdminHermesMemoryStatus('正在生成 Hermes 记忆 ZIP 备份...');
  const resp = await fetch('/api/admin/hermes/memory-backup', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({tenant_slug: tenantSlug, range_key: rangeKey}),
  });
  if (!resp.ok) {
    let errorMessage = 'hermes_memory_backup_failed';
    try {
      const data = await resp.json();
      errorMessage = (data && data.error) || errorMessage;
    } catch (error) {}
    setAdminHermesMemoryStatus(errorMessage, true);
    showToast(errorMessage);
    return false;
  }
  const blob = await resp.blob();
  const downloadUrl = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = downloadUrl;
  link.download = (() => {
    const contentDisposition = resp.headers.get('Content-Disposition') || '';
    const matched = contentDisposition.match(/filename=\"([^\"]+)\"/);
    return matched ? matched[1] : `hermes_memory_${tenantSlug}_${rangeKey}.zip`;
  })();
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(downloadUrl);
  setAdminHermesMemoryStatus(`Hermes 记忆备份已生成 · ${tenantSlug} · ${rangeKey}`);
  showToast('Hermes 记忆 ZIP 备份已下载');
  return true;
}

async function clearAdminHermesMemory(backupFirst) {
  const tenantSlug = getAdminHermesMemorySelectedTenant();
  const rangeKey = document.getElementById('admin-hermes-memory-clear-range')?.value || '3m';
  const confirmText = document.getElementById('admin-hermes-memory-clear-confirm')?.value || '';
  if (!tenantSlug) {
    showToast('请先选择租户');
    return;
  }
  if (rangeKey === 'all' && String(confirmText).trim() !== 'CONFIRM') {
    showToast('全量清理前请输入 CONFIRM');
    return;
  }
  if (backupFirst) {
    const backupOk = await backupAdminHermesMemory();
    if (!backupOk) return;
  }
  const preview = adminHermesMemoryState.preview || {};
  const turnCount = Number(preview.turns_to_clear || 0);
  const confirmed = window.confirm(
    rangeKey === 'all'
      ? `确认清空租户 ${tenantSlug} 的全部 Hermes 记忆吗？当前预估删除 ${turnCount} 轮对话。`
      : `确认清理租户 ${tenantSlug} 的 Hermes 记忆吗？当前预估删除 ${turnCount} 轮对话。`
  );
  if (!confirmed) return;
  setAdminHermesMemoryStatus('正在执行 Hermes 记忆清理...');
  const resp = await fetch('/api/admin/hermes/memory-clear', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({tenant_slug: tenantSlug, range_key: rangeKey, confirm_text: confirmText}),
  });
  const data = await resp.json();
  if (!resp.ok || !data.ok) {
    const errorMessage = (data && data.error) || 'hermes_memory_clear_failed';
    setAdminHermesMemoryStatus(errorMessage, true);
    showToast(errorMessage);
    return;
  }
  adminHermesMemoryState.summary = data.result && data.result.post_summary ? data.result.post_summary : adminHermesMemoryState.summary;
  adminHermesMemoryState.preview = null;
  if (document.getElementById('admin-hermes-memory-clear-confirm')) {
    document.getElementById('admin-hermes-memory-clear-confirm').value = '';
  }
  renderAdminHermesMemoryPanel();
  await previewAdminHermesMemoryClear(false);
  setAdminHermesMemoryStatus(`Hermes 记忆清理完成 · ${tenantSlug} · ${rangeKey}`);
  showToast('Hermes 记忆已清理并完成重建');
}

