  const board = document.getElementById('forecast-workflow-board');
  const summary = document.getElementById('forecast-workflow-summary');
  const stats = document.getElementById('forecast-graph-stats');
  const preview = forecastWorkflowMeta.preview || {};
  if (summary) {
    const result = preview.result || {};
    summary.textContent = result.predicted_change_pct !== undefined
      ? `当前示例预览目标 ${Number(result.predicted_change_pct || 0).toFixed(2)}%，波动上限 ${Number(result.volatility_cap || 0).toFixed(2)}%。`
      : (forecastWorkflowMeta.summary || '展示目标价是怎么计算出来的，并允许在后台调整自动收敛参数。');
  }
  if (stats) {
    stats.textContent = `${(forecastGraph.nodes || []).length} 节点 · ${(forecastGraph.edges || []).length} 连线 · 当前算法`;
  }
  if (!board) return;
  const graph = forecastWorkflowMeta.graph || forecastGraph;
  const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
  applyForecastZoom();
  if (!nodes.length) {
    board.innerHTML = `<div class="compact-row"><strong>暂无工作流节点</strong><span>0</span></div>`;
    const edgeLayer = document.getElementById('forecast-edge-layer');
    if (edgeLayer) edgeLayer.innerHTML = '';
    return;
  }
  board.innerHTML = nodes.map((item) => `
    <article class="workflow-node ${item.id === selectedForecastNodeId ? 'is-selected' : ''} ${forecastLinkState?.from === item.id ? 'is-link-source' : ''}" data-node-id="${escapeAttr(item.id || '')}" style="left:${Number(item.x || 0)}px;top:${Number(item.y || 0)}px;">
      <div class="workflow-node-head">
        <strong>${escapeHtml(item.label || item.id || '-')}</strong>
        <span class="workflow-node-type">${escapeHtml(item.processor || '')}</span>
      </div>
      <div class="workflow-node-ports">
        <button type="button" class="workflow-port" data-port-action="select" data-node-id="${escapeAttr(item.id || '')}">接入</button>
        <button type="button" class="workflow-port" data-port-action="link" data-node-id="${escapeAttr(item.id || '')}">连出</button>
      </div>
    </article>
  `).join('');
  bindForecastGraphEvents();
  renderForecastEdges();
  renderForecastCatalog();
}

function renderForecastConfigBoard() {
  const board = document.getElementById('forecast-config-board');
  if (!board) return;
  const selectedNode = (forecastGraph.nodes || []).find((item) => item.id === selectedForecastNodeId) || null;
  const catalog = Array.isArray(forecastWorkflowMeta.catalog) ? forecastWorkflowMeta.catalog : [];
  const nodeSpec = selectedNode ? catalog.find((item) => item.processor === selectedNode.processor) : null;
  const tuningEntries = Object.entries(forecastConfig || {});
  const paramFields = Array.isArray(nodeSpec?.params) ? nodeSpec.params : [];
  const debugBlock = renderForecastNodeDebug();
  const selectedBlock = selectedNode ? `
    <div class="forecast-inspector-section">
      <div class="forecast-config-section-title">节点参数</div>
      <label class="forecast-config-field">
        <span>节点名称</span>
        <div class="forecast-config-input">
          <input data-node-label value="${escapeAttr(String(selectedNode.label || ''))}">
          <em>label</em>
        </div>
      </label>
      ${paramFields.length ? paramFields.map((field) => `
        <label class="forecast-config-field">
          <span>${escapeHtml(field.label || field.key || '-')}</span>
          <div class="forecast-config-input">
            <input data-node-param="${escapeAttr(field.key || '')}" value="${escapeAttr(String(selectedNode.params?.[field.key] ?? ''))}">
            <em>${escapeHtml(field.kind || '')}</em>
          </div>
        </label>
      `).join('') : `<div class="compact-row"><strong>当前节点无独立参数</strong><span>${escapeHtml(selectedNode.processor || '')}</span></div>`}
    </div>
  ` : `<div class="compact-row"><strong>未选中节点</strong><span>点击画布节点后编辑参数</span></div>`;
  board.innerHTML = `
    ${selectedBlock}
    <div class="forecast-inspector-section">
      <div class="forecast-config-section-title">节点预览</div>
      ${debugBlock}
    </div>
    <details class="forecast-inspector-section">
      <summary class="forecast-advanced-toggle">高级参数</summary>
      ${tuningEntries.map(([key, value]) => `
        <label class="forecast-config-field">
          <span>${escapeHtml(key)}</span>
          <div class="forecast-config-input">
            <input data-forecast-field="${escapeAttr(key)}" inputmode="decimal" step="0.05" value="${escapeAttr(String(value ?? ''))}">
            <em>tuning</em>
          </div>
        </label>
      `).join('')}
    </details>
    ${selectedNode ? `
      <div class="workflow-inspector-actions">
        <button type="button" class="btn-outline workflow-tool-button" id="forecast-delete-node">删除节点</button>
      </div>
    ` : ''}
  `;
  document.getElementById('forecast-delete-node')?.addEventListener('click', deleteSelectedForecastNode);
}

function renderForecastNodeDebug() {
  const selectedNode = (forecastGraph.nodes || []).find((item) => item.id === selectedForecastNodeId) || null;
  const nodeResults = forecastWorkflowMeta.preview?.node_results || forecastWorkflowMeta.graph?.node_results || {};
  if (!selectedNode) {
    return `<div class="compact-row"><strong>未选中节点</strong><span>暂无调试信息</span></div>`;
  }
  const debug = nodeResults[selectedNode.id];
  if (!debug) {
    return `<div class="compact-row"><strong>${escapeHtml(selectedNode.label || selectedNode.id || '-')}</strong><span>暂无运行结果</span></div>`;
  }
  const preview = debug.context_preview && typeof debug.context_preview === 'object'
    ? Object.entries(debug.context_preview).map(([key, value]) => `<div class="result-line"><strong>${escapeHtml(key)}</strong> · ${escapeHtml(String(value))}</div>`).join('')
    : `<div class="result-line">暂无上下文预览</div>`;
  return `
    <div class="forecast-config-field">
      <span>当前输出</span>
      <div class="forecast-debug-value">${escapeHtml(String(debug.value ?? '--'))}</div>
    </div>
    <div class="forecast-config-field">
      <span>计算公式</span>
      <div class="forecast-debug-copy">${escapeHtml(debug.formula || '暂无')}</div>
    </div>
    <div class="forecast-config-field">
      <span>说明</span>
      <div class="forecast-debug-copy">${escapeHtml(debug.note || '暂无')}</div>
    </div>
    <div class="forecast-config-field">
      <span>上下文预览</span>
      <div class="forecast-debug-list">${preview}</div>
    </div>
  `;
}

function renderForecastCatalog() {
  const host = document.getElementById('forecast-node-catalog');
  if (!host) return;
  const catalog = Array.isArray(forecastWorkflowMeta.catalog) ? forecastWorkflowMeta.catalog : [];
  host.innerHTML = catalog.map((item) => `
    <button type="button" class="workflow-catalog-item" data-add-processor="${escapeAttr(item.processor || '')}">
      <strong>${escapeHtml(item.label || item.processor || '-')}</strong>
      <span>${escapeHtml(item.description || '')}</span>
    </button>
  `).join('');
  host.querySelectorAll('[data-add-processor]').forEach((node) => {
    node.addEventListener('click', () => addForecastNode(node.dataset.addProcessor || 'source'));
  });
}

function renderForecastEdges() {
  const layer = document.getElementById('forecast-edge-layer');
  const board = document.getElementById('forecast-workflow-board');
  const viewport = document.getElementById('forecast-stage-viewport');
  if (!layer || !board) return;
  const nodes = Array.isArray(forecastGraph.nodes) ? forecastGraph.nodes : [];
  const edges = Array.isArray(forecastGraph.edges) ? forecastGraph.edges : [];
  const width = Math.max(1800, ...nodes.map((item) => Number(item.x || 0) + 280));
  const height = Math.max(760, ...nodes.map((item) => Number(item.y || 0) + 180));
  board.style.width = `${width}px`;
  board.style.height = `${height}px`;
  if (viewport) {
    viewport.style.width = `${width}px`;
    viewport.style.height = `${height}px`;
  }
  layer.setAttribute('width', String(width));
  layer.setAttribute('height', String(height));
  layer.setAttribute('viewBox', `0 0 ${width} ${height}`);
  layer.innerHTML = `
    <defs>
      <marker id="workflow-arrowhead" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="12" markerHeight="12" markerUnits="userSpaceOnUse" orient="auto">
        <path d="M 0 1 L 11 6 L 0 11 z" fill="rgba(47, 116, 192, 0.96)"></path>
      </marker>
    </defs>
    ${edges.map((edge) => {
      const fromNode = nodes.find((item) => item.id === edge.from);
      const toNode = nodes.find((item) => item.id === edge.to);
      if (!fromNode || !toNode) return '';
      const startX = Number(fromNode.x || 0) + 220;
      const startY = Number(fromNode.y || 0) + 52;
      const endX = Number(toNode.x || 0);
      const endY = Number(toNode.y || 0) + 52;
      const deltaX = endX - startX;
      const controlOffset = Math.max(80, Math.min(180, Math.abs(deltaX) * 0.45));
      const controlA = startX + (deltaX >= 0 ? controlOffset : -controlOffset);
      const controlB = endX - (deltaX >= 0 ? controlOffset : -controlOffset);
      const path = `M ${startX} ${startY} C ${controlA} ${startY}, ${controlB} ${endY}, ${endX} ${endY}`;
      return `
        <g data-edge-id="${escapeAttr(edge.id || '')}">
          <path class="workflow-edge-shadow" d="${path}"></path>
          <path class="workflow-edge" d="${path}" marker-end="url(#workflow-arrowhead)"></path>
          <circle class="workflow-edge-anchor" cx="${startX}" cy="${startY}" r="5"></circle>
          <circle class="workflow-edge-anchor" cx="${endX}" cy="${endY}" r="5"></circle>
        </g>
      `;
    }).join('')}
  `;
}

function applyForecastZoom() {
  const viewport = document.getElementById('forecast-stage-viewport');
  if (!viewport) return;
  viewport.style.transform = `scale(${forecastZoom})`;
  viewport.dataset.zoom = String(forecastZoom);
}

function bindForecastGraphEvents() {
  document.querySelectorAll('.workflow-node').forEach((node) => {
    node.addEventListener('click', (event) => {
      if (event.target instanceof HTMLElement && event.target.dataset.portAction) return;
      selectedForecastNodeId = node.dataset.nodeId || '';
      renderForecastWorkflow();
      renderForecastConfigBoard();
      renderForecastNodeDebug();
    });
    node.addEventListener('pointerdown', (event) => {
      if (event.target instanceof HTMLElement && event.target.dataset.portAction) return;
      const nodeId = node.dataset.nodeId || '';
      const item = (forecastGraph.nodes || []).find((row) => row.id === nodeId);
      if (!item) return;
      selectedForecastNodeId = nodeId;
      forecastDragState = {
        nodeId,
        startX: event.clientX,
        startY: event.clientY,
        originX: Number(item.x || 0),
        originY: Number(item.y || 0),
      };
      node.setPointerCapture?.(event.pointerId);
    });
  });
  document.querySelectorAll('[data-port-action="link"]').forEach((node) => {
    node.addEventListener('pointerdown', (event) => {
      const target = event.currentTarget;
      if (!(target instanceof HTMLElement)) return;
      forecastLinkState = {from: target.dataset.nodeId || ''};
      renderForecastWorkflow();
      renderForecastConfigBoard();
      event.preventDefault();
    });
    node.addEventListener('click', (event) => {
      const target = event.currentTarget;
      if (!(target instanceof HTMLElement)) return;
      forecastLinkState = {from: target.dataset.nodeId || ''};
      renderForecastWorkflow();
      renderForecastConfigBoard();
    });
  });
  document.querySelectorAll('[data-port-action="select"]').forEach((node) => {
    node.addEventListener('pointerup', (event) => {
      const target = event.currentTarget;
      if (!(target instanceof HTMLElement)) return;
      const nodeId = target.dataset.nodeId || '';
      if (forecastLinkState?.from && forecastLinkState.from !== nodeId) {
        addForecastEdge(forecastLinkState.from, nodeId);
        forecastLinkState = null;
        renderForecastWorkflow();
        renderForecastConfigBoard();
        renderForecastNodeDebug();
        showToast('连线已完成');
        event.preventDefault();
      }
    });
    node.addEventListener('click', (event) => {
      const target = event.currentTarget;
      if (!(target instanceof HTMLElement)) return;
      const nodeId = target.dataset.nodeId || '';
      if (forecastLinkState?.from && forecastLinkState.from !== nodeId) {
        addForecastEdge(forecastLinkState.from, nodeId);
        forecastLinkState = null;
        renderForecastWorkflow();
        renderForecastConfigBoard();
        renderForecastNodeDebug();
        showToast('连线已完成');
        return;
      }
      selectedForecastNodeId = nodeId;
      renderForecastWorkflow();
      renderForecastConfigBoard();
      renderForecastNodeDebug();
    });
  });
}

window.addEventListener('pointermove', (event) => {
  if (!forecastDragState) return;
  const item = (forecastGraph.nodes || []).find((row) => row.id === forecastDragState.nodeId);
  if (!item) return;
  const zoom = forecastZoom || 1;
  item.x = Math.max(8, forecastDragState.originX + (event.clientX - forecastDragState.startX) / zoom);
  item.y = Math.max(8, forecastDragState.originY + (event.clientY - forecastDragState.startY) / zoom);
  renderForecastWorkflow();
  renderForecastConfigBoard();
  renderForecastNodeDebug();
});

window.addEventListener('pointerup', () => {
  forecastDragState = null;
});

function addForecastNode(processor) {
  const catalog = Array.isArray(forecastWorkflowMeta.catalog) ? forecastWorkflowMeta.catalog : [];
  const spec = catalog.find((item) => item.processor === processor) || {label: processor, params: []};
  const nextIndex = (forecastGraph.nodes || []).length + 1;
  const nodeId = `${processor}_${Date.now()}_${nextIndex}`;
  const params = {};
  (spec.params || []).forEach((item) => {
    params[item.key] = '';
  });
  forecastGraph.nodes.push({
    id: nodeId,
    label: spec.label || processor,
    processor,
    x: 120 + (nextIndex % 3) * 260,
    y: 120 + Math.floor(nextIndex / 3) * 120,
    params,
  });
  selectedForecastNodeId = nodeId;
  renderForecastWorkflow();
  renderForecastConfigBoard();
  renderForecastNodeDebug();
}

function addForecastEdge(fromId, toId) {
  if (!fromId || !toId || fromId === toId) return;
  if ((forecastGraph.edges || []).some((item) => item.from === fromId && item.to === toId)) return;
  forecastGraph.edges.push({id: `edge_${Date.now()}_${forecastGraph.edges.length + 1}`, from: fromId, to: toId});
}

function deleteSelectedForecastNode() {
  if (!selectedForecastNodeId) return;
  forecastGraph.nodes = (forecastGraph.nodes || []).filter((item) => item.id !== selectedForecastNodeId);
  forecastGraph.edges = (forecastGraph.edges || []).filter((item) => item.from !== selectedForecastNodeId && item.to !== selectedForecastNodeId);
  selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
  renderForecastWorkflow();
  renderForecastConfigBoard();
  renderForecastNodeDebug();
}

function centerForecastView() {
  const stage = document.querySelector('#section-forecast-model .workflow-stage');
  const viewport = document.getElementById('forecast-stage-viewport');
  if (!stage) return;
  const targetWidth = viewport ? viewport.offsetWidth * forecastZoom : stage.scrollWidth;
  const targetHeight = viewport ? viewport.offsetHeight * forecastZoom : stage.scrollHeight;
  stage.scrollLeft = Math.max(0, (targetWidth - stage.clientWidth) / 2);
  stage.scrollTop = Math.max(0, (targetHeight - stage.clientHeight) / 2);
}

function collectForecastConfig() {
  document.querySelectorAll('[data-forecast-field]').forEach((fieldNode) => {
    const field = fieldNode.dataset.forecastField;
    if (!field) return;
    forecastConfig[field] = Number(fieldNode.value || 0);
  });
  const selectedNode = (forecastGraph.nodes || []).find((item) => item.id === selectedForecastNodeId);
  if (selectedNode) {
    const labelNode = document.querySelector('[data-node-label]');
    if (labelNode instanceof HTMLInputElement) {
      selectedNode.label = labelNode.value || selectedNode.label;
    }
    document.querySelectorAll('[data-node-param]').forEach((fieldNode) => {
      const field = fieldNode.dataset.nodeParam;
      if (!field) return;
      selectedNode.params = selectedNode.params || {};
      selectedNode.params[field] = fieldNode.value;
    });
  }
  forecastGraph.tuning = {...forecastConfig};
}

async function loadAdminForecastModel(forceReload) {
  if (forecastLoaded && !forceReload && forecastEditorBootstrapped) return;
  const payload = await fetch('/api/admin/forecast-config');
  const data = await payload.json();
  if (!payload.ok || data.ok === false) throw new Error(data.error || 'forecast_config_failed');
  forecastConfig = data.config || {};
  forecastWorkflowMeta = data.workflow_meta || {};
  forecastGraph = forecastWorkflowMeta.graph || {nodes: [], edges: [], tuning: forecastConfig};
  forecastGraph.tuning = {...forecastConfig};
  selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
  forecastLoaded = true;
  renderForecastWorkflow();
  renderForecastConfigBoard();
  renderForecastNodeDebug();
  centerForecastView();
}

async function resetAdminForecastGraph() {
  const statusNode = document.getElementById('forecast-save-status');
  if (statusNode) statusNode.textContent = '正在恢复推荐模板...';
  const res = await fetch('/api/admin/forecast-config', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({reset_default: true}),
  });
  const data = await res.json();
  if (!res.ok || data.ok === false) throw new Error(data.error || 'reset_failed');
  forecastConfig = data.config || {};
  forecastWorkflowMeta = data.workflow_meta || {};
  forecastGraph = forecastWorkflowMeta.graph || {nodes: [], edges: [], tuning: forecastConfig};
  forecastGraph.tuning = {...forecastConfig};
  selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
  forecastLoaded = true;
  renderForecastWorkflow();
  renderForecastConfigBoard();
  renderForecastNodeDebug();
  centerForecastView();
  if (statusNode) statusNode.textContent = '已恢复推荐模板';
  showToast('已恢复推荐模板');
}

async function saveForecastConfigs() {
  collectForecastConfig();
  const statusNode = document.getElementById('forecast-save-status');
  if (statusNode) statusNode.textContent = '保存中...';
  const res = await fetch('/api/admin/forecast-config', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({graph: {...forecastGraph, tuning: forecastConfig}, config: forecastConfig}),
  });
  const data = await res.json();
  if (!res.ok || data.ok === false) throw new Error(data.error || 'save_failed');
  forecastConfig = data.config || {};
  forecastWorkflowMeta = data.workflow_meta || {};
  forecastGraph = forecastWorkflowMeta.graph || forecastGraph;
  forecastGraph.tuning = {...forecastConfig};
  selectedForecastNodeId = (forecastGraph.nodes || [])[0]?.id || '';
  renderForecastWorkflow();
  renderForecastConfigBoard();
  renderForecastNodeDebug();
  if (statusNode) statusNode.textContent = '预测算法配置已保存';
  showToast('预测算法配置已保存');
}

function initForecastEditorEvents() {
  if (forecastEditorBootstrapped) return;
  forecastEditorBootstrapped = true;
  document.getElementById('save-forecast-configs')?.addEventListener('click', async () => {
    try {
      await saveForecastConfigs();
    } catch (error) {
      showToast(error.message || '保存失败');
    }
  });
  document.getElementById('forecast-reset-graph')?.addEventListener('click', async () => {
    try {
      await resetAdminForecastGraph();
    } catch (error) {
      showToast(error.message || '恢复失败');
    }
  });
  document.getElementById('forecast-center-view')?.addEventListener('click', () => {
    centerForecastView();
  });
  document.getElementById('forecast-zoom-in')?.addEventListener('click', () => {
    forecastZoom = Math.min(1.8, Number((forecastZoom + 0.1).toFixed(2)));
    applyForecastZoom();
  });
  document.getElementById('forecast-zoom-out')?.addEventListener('click', () => {
    forecastZoom = Math.max(0.6, Number((forecastZoom - 0.1).toFixed(2)));
    applyForecastZoom();
  });
}

let adminSiteConfig = JSON.parse(JSON.stringify(window.SITE_CONFIG || {}));
let adminSiteConfigLoaded = false;

function ensureAdminLlmRegistry() {
  if (!adminSiteConfig.llm_registry || typeof adminSiteConfig.llm_registry !== 'object') {
    adminSiteConfig.llm_registry = { default_model_key: '', models: [], feature_model_keys: {} };
  }
  if (!Array.isArray(adminSiteConfig.llm_registry.models)) {
    adminSiteConfig.llm_registry.models = [];
  }
  if (!adminSiteConfig.llm_registry.feature_model_keys || typeof adminSiteConfig.llm_registry.feature_model_keys !== 'object') {
    adminSiteConfig.llm_registry.feature_model_keys = {};
  }
  return adminSiteConfig.llm_registry;
}

function addAdminLlmModel() {
  const registry = ensureAdminLlmRegistry();
  const nextIndex = registry.models.length + 1;
  registry.models.push({
    key: `model_${nextIndex}`,
    label: `模型 ${nextIndex}`,
    provider: 'openai',
    model_name: '',
    base_url: '',
    api_key: '',
    purpose: 'general',
    enabled: true,
  });
  if (!registry.default_model_key) {
    registry.default_model_key = registry.models[registry.models.length - 1].key;
  }
  renderSiteConfigForm();
}

function updateAdminLlmModel(index, field, value) {
  const registry = ensureAdminLlmRegistry();
  if (!registry.models[index]) return;
  const previousKey = registry.models[index].key || '';
  registry.models[index][field] = field === 'enabled' ? Boolean(value) : value;
  if (field === 'key' && registry.default_model_key === previousKey) {
    registry.default_model_key = value;
  }
  renderSiteConfigForm();
}

function updateAdminLlmApiKey(index, value) {
  const registry = ensureAdminLlmRegistry();
  if (!registry.models[index]) return;
  // Keep the secret input mounted while typing. Re-rendering the whole model
  // list on every keystroke loses focus and makes the field appear unusable.
  registry.models[index].api_key = String(value || '');
  registry.models[index].clear_api_key = false;
}

async function toggleAdminLlmApiKeyVisibility(index) {
  const input = document.getElementById(`llm-api-key-${index}`);
  const button = document.getElementById(`llm-api-key-toggle-${index}`);
  if (!input) return;
  const registry = ensureAdminLlmRegistry();
  const model = registry.models[index] || {};
  if (!input.value && model.api_key_configured) {
    await revealAdminLlmApiKey(index, button);
    return;
  }
  const visible = input.type === 'text';
  input.type = visible ? 'password' : 'text';
  if (button) button.textContent = visible ? '显示' : '隐藏';
}

async function revealAdminLlmApiKey(index, buttonOverride) {
  const registry = ensureAdminLlmRegistry();
  const model = registry.models[index];
  const input = document.getElementById(`llm-api-key-${index}`);
  const button = buttonOverride || document.getElementById(`llm-api-key-toggle-${index}`);
  if (!model || !input || !button) return;
  if (input.value) {
    input.type = 'text';
    document.getElementById(`llm-api-key-toggle-${index}`).textContent = '隐藏';
    return;
  }
  const originalText = button.textContent;
  button.disabled = true;
  button.textContent = '读取中';
  try {
    const response = await fetch('/api/admin/llm-credentials/reveal', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      cache: 'no-store',
      body: JSON.stringify({model_key: String(model.key || '')}),
    });
    const rawResponse = await response.text();
    let data = {};
    try {
      data = rawResponse ? JSON.parse(rawResponse) : {};
    } catch (parseError) {
      if (response.redirected || response.status === 401 || response.status === 403) {
        throw new Error('管理员登录已失效，请重新登录后再查看 API Key');
      }
      throw new Error(`服务器未返回有效结果（HTTP ${response.status}），请重启或重新部署 5001 服务`);
    }
    if (!response.ok || !data.ok) {
      const messages = {
        llm_api_key_not_configured: '该模型尚未配置 API Key',
        model_key_required: '模型配置无效',
      };
      throw new Error(messages[data && data.error] || (data && data.error) || '读取 API Key 失败');
    }
    input.value = String(data.api_key || '');
    model.api_key = input.value;
    input.type = 'text';
    document.getElementById(`llm-api-key-toggle-${index}`).textContent = '隐藏';
  } catch (error) {
    if (typeof showToast === 'function') showToast(String(error && error.message || '读取 API Key 失败'));
  } finally {
    button.disabled = false;
    button.textContent = originalText;
  }
}

function removeAdminLlmModel(index) {
  const registry = ensureAdminLlmRegistry();
  const current = registry.models[index];
  if (!current) return;
  const removedKey = current.key;
  registry.models.splice(index, 1);
  if (registry.default_model_key === removedKey) {
    registry.default_model_key = registry.models[0] ? registry.models[0].key : '';
  }
  renderSiteConfigForm();
}

