function updateAdminLlmFeatureModel(featureCode, modelKey) {
  const registry = ensureAdminLlmRegistry();
  const code = String(featureCode || '').trim();
  const key = String(modelKey || '').trim();
  if (!code) return;
  if (!key) {
    delete registry.feature_model_keys[code];
  } else {
    registry.feature_model_keys[code] = key;
  }
  renderSiteConfigForm();
}

function updateAdminLlmDefaultModel(key) {
  const registry = ensureAdminLlmRegistry();
  registry.default_model_key = key || '';
  renderSiteConfigForm();
}

function applyAdminLlmPurposePreset(index, purpose) {
  updateAdminLlmModel(index, 'purpose', purpose || 'general');
}

function commitAdminLlmPurposeInput(index, inputEl) {
  if (!inputEl) return;
  const nextValue = String(inputEl.value || '').trim().toLowerCase();
  if (!nextValue) {
    inputEl.value = '';
    return;
  }
  updateAdminLlmModel(index, 'purpose', nextValue);
}

function handleAdminLlmPurposeKeydown(index, event) {
  if (!event) return;
  if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    commitAdminLlmPurposeInput(index, event.target);
  }
}

function clearAdminLlmPurpose(index) {
  updateAdminLlmModel(index, 'purpose', '');
}
let selectedAdminTenantIndex = 0;
let adminSiteConfigDirty = false;
const SITE_CONFIG_BROADCAST_KEY = 'gangtise-site-config-updated-at';

function isAdminFeatureEnabled(featureName) {
  const flags = (adminSiteConfig && adminSiteConfig.feature_flags) || {};
  if (featureName === 'knowledge' && flags.knowledge_module_enabled !== true) return false;
  if (featureName === 'core_indicators') return flags.core_indicators === true;
  return flags[featureName] !== false;
}

function markAdminSiteConfigDirty(message) {
  adminSiteConfigDirty = true;
  const status = document.getElementById('site-config-status');
  const featureStatus = document.getElementById('feature-config-status');
  const nextMessage = message || '有未保存的修改。点击保存后才会同步到 Admin、大V工作台和 H5。';
  if (status) status.textContent = nextMessage;
  if (featureStatus) featureStatus.textContent = nextMessage;
}

function markAdminSiteConfigSaved(message) {
  adminSiteConfigDirty = false;
  const status = document.getElementById('site-config-status');
  const featureStatus = document.getElementById('feature-config-status');
  const nextMessage = message || '已保存。功能开关会同步影响 Admin、大V工作台和 H5。';
  if (status) status.textContent = nextMessage;
  if (featureStatus) featureStatus.textContent = nextMessage;
}

function broadcastSiteConfigUpdate() {
  try {
    window.localStorage.setItem(SITE_CONFIG_BROADCAST_KEY, String(Date.now()));
  } catch (error) {
    // ignore storage write failures
  }
}

function isAdminSiteConfigField(target) {
  if (!target || !target.closest) return false;
  return Boolean(target.closest('#section-settings-features, #section-settings-appearance, #section-settings-brand, #section-settings-policy, #section-settings-knowledge, #section-settings-llm, #section-settings-llm-features'));
}

function updateAdminFeatureFlagPreview(target) {
  if (!target || !target.id || !target.id.startsWith('feature-')) return;
  if (!adminSiteConfig || typeof adminSiteConfig !== 'object') return;
  adminSiteConfig.feature_flags = adminSiteConfig.feature_flags || {};
  const key = target.id.replace(/^feature-/, '');
  adminSiteConfig.feature_flags[key] = Boolean(target.checked);
  if (key === 'knowledge') {
    adminSiteConfig.feature_flags.knowledge_module_enabled = Boolean(target.checked);
  }
  refreshAdminNavVisibility();
  if (key === 'tenant_portal') renderTenantConfigList();
  const forecastSection = document.getElementById('section-forecast-model');
  if (forecastSection && key === 'stock_forecast' && !target.checked && forecastSection.style.display !== 'none') {
    showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
  }
  const hermesSection = document.getElementById('section-hermes');
  if (hermesSection && key === 'hermes' && !target.checked && hermesSection.style.display !== 'none') {
    showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
  }
}

function refreshAdminNavVisibility() {
  document.querySelectorAll('.admin-nav-item[data-feature]').forEach((node) => {
    const featureName = node.dataset.feature;
    const forceHidden = node.dataset.unifiedHidden === 'true';
    node.style.display = isAdminFeatureEnabled(featureName) && !forceHidden ? '' : 'none';
  });
  document.querySelectorAll('.admin-nav-group').forEach((group) => {
    const items = Array.from(group.querySelectorAll('.admin-nav-item'));
    const visibleItems = items.filter((item) => item.style.display !== 'none');
    group.style.display = visibleItems.length ? '' : 'none';
  });
  const activeSection = document.querySelector('.admin-nav-item.active[data-section]');
  if (activeSection && activeSection.style.display === 'none') {
    showSection('overview', document.querySelector('.admin-nav-item[data-section="overview"]'));
  }
}

function ensureAdminTenants() {
  if (!Array.isArray(adminSiteConfig.tenants) || !adminSiteConfig.tenants.length) {
    adminSiteConfig.tenants = [];
  }
  adminSiteConfig.tenants.forEach((tenant) => ensureAdminTenantNewsAggregationAlgorithm(tenant));
  return adminSiteConfig.tenants;
}

function getAdminNewsAggregationAlgorithmDefaults() {
  const defaults = (adminSiteConfig && adminSiteConfig.news_aggregation_algorithm_defaults) || {};
  if (typeof defaults.script_js !== 'string' || !defaults.script_js.trim()) {
    defaults.script_js = [
      'function rankNews(input) {',
      "  const normalize = (value) => String(value || '').replace(/[\s\u3000·•/|_|-]+/g, ' ').trim();",
      "  const compact = (value) => String(value || '').replace(/[\s\u3000·•/|_|-.]/g, '').trim();",
      '  const tags = Array.isArray(input.item.tags) ? input.item.tags.map(normalize).filter(Boolean) : [];',
      "  const text = normalize([input.item.title, input.item.content, input.item.summary].filter(Boolean).join(' '));",
      '  const compactText = compact(text);',
      '  const sectorTokens = Array.isArray(input.watchlistSectors) ? input.watchlistSectors.map(normalize).filter(Boolean) : [];',
      "  const sectorAliases = {'港股互联网':['互联网','平台经济','港股','腾讯','阿里','美团','百度','快手'],'半导体制造':['半导体','芯片','集成电路','晶圆','存储','光刻'],'高端白酒':['白酒','贵州茅台','五粮液','泸州老窖'],'动力电池':['动力电池','锂电','新能源车','宁德时代'],'银行':['银行','信贷','息差','存款','贷款']};",
      '  const symbolTokens = Array.isArray(input.watchlistSymbols) ? input.watchlistSymbols.map(normalize).filter(Boolean) : [];',
      "  const majorKeywords = ['重大利好','重大利空','重大风险','突发','紧急','重磅','立案调查','行政处罚','停牌','退市','暴雷','违约','降准','降息','加息','出口管制','关税上调','重大订单','中标','业绩预增','业绩预亏','回购','增持','减持','并购重组','重大资产重组'];",
      "  const sectorMatch = sectorTokens.some(tag => [tag, ...(sectorAliases[tag] || [])].some(term => text.includes(term)));",
      "  const symbolMatch = symbolTokens.some(tag => text.includes(tag) || compactText.includes(compact(tag)));",
      "  const majorSignal = Boolean(input.item.isMajorPositive || input.item.isMajorNegative) || majorKeywords.some(keyword => text.includes(keyword));",
      '  return {',
      "    score: ((sectorMatch || symbolMatch) ? 220 : 0) + (symbolMatch ? 65 : 0) + (majorSignal ? 100 : 0),",
      "    bucket: (sectorMatch || symbolMatch) ? 'watchlist_sector' : (majorSignal ? 'major_market' : 'other'),",
      "    reason: (sectorMatch || symbolMatch) ? '命中自选股行业板块或标的' : (majorSignal ? '命中社会性重大利好/利空或高影响事件' : '其他公开信息'),",
      '    matched_topics: [',
      '      ...new Set([',
      '        ...sectorTokens.filter(tag => [tag, ...(sectorAliases[tag] || [])].some(term => text.includes(term))),',
      '        ...symbolTokens.filter(tag => text.includes(tag) || compactText.includes(compact(tag))),',
      '        ...majorKeywords.filter(keyword => text.includes(keyword))',
      '      ])',
      '    ]',
      '  };',
      '}',
    ].join('\n');
  }
  if (!defaults.version) defaults.version = 'v3';
  if (!defaults.strategy) defaults.strategy = 'watchlist_sector_first';
  return defaults;
}

function ensureAdminTenantNewsAggregationAlgorithm(tenant) {
  if (!tenant || typeof tenant !== 'object') return { version: 'v3', strategy: 'watchlist_sector_first', script_js: '' };
  const defaults = getAdminNewsAggregationAlgorithmDefaults();
  if (!tenant.news_aggregation_algorithm || typeof tenant.news_aggregation_algorithm !== 'object') {
    tenant.news_aggregation_algorithm = {
      version: defaults.version || 'v3',
      strategy: defaults.strategy || 'watchlist_sector_first',
      script_js: defaults.script_js || '',
      source_prompt: '',
      updated_at: '',
      updated_by: 'admin',
    };
  }
  if (typeof tenant.news_aggregation_algorithm.script_js !== 'string') {
    tenant.news_aggregation_algorithm.script_js = String(tenant.news_aggregation_algorithm.script_js || '');
  }
  if (!tenant.news_aggregation_algorithm.script_js.trim()) {
    tenant.news_aggregation_algorithm.script_js = defaults.script_js || '';
  }
  if (!tenant.news_aggregation_algorithm.version) {
    tenant.news_aggregation_algorithm.version = defaults.version || 'v3';
  }
  if (!tenant.news_aggregation_algorithm.strategy) {
    tenant.news_aggregation_algorithm.strategy = defaults.strategy || 'watchlist_sector_first';
  }
  return tenant.news_aggregation_algorithm;
}

function buildNewAdminTenant(index) {
  const serial = index + 1;
  const algorithmDefaults = getAdminNewsAggregationAlgorithmDefaults();
  return {
    id: `tenant_custom_${serial}`,
    slug: `tenant-${serial}`,
    name: `新租户 ${serial}`,
    short_name: `租户${serial}`,
    logo_mark: '⭐',
    advisor: `待命名大V ${serial}`,
    tier: '观察租户',
    focus: '',
    rights: '',
    description: '',
    portal_headline: '',
    portal_description: '',
    dashboard_title: '',
    dashboard_description: '',
    news_aggregation_algorithm: {
      version: algorithmDefaults.version || 'v3',
      strategy: algorithmDefaults.strategy || 'watchlist_sector_first',
      script_js: algorithmDefaults.script_js || '',
      source_prompt: '',
      updated_at: '',
      updated_by: 'admin',
    },
  };
}

function sanitizeTenantSlug(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9-_]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^-|-$/g, '');
}

function updateTenantSummaryCards() {
  const tenants = ensureAdminTenants();
  const totalNode = document.getElementById('tenant-total-count');
  const defaultNode = document.getElementById('tenant-default-name');
  if (totalNode) totalNode.textContent = String(tenants.length);
  const defaultSlug = adminSiteConfig.default_tenant_slug || '';
  const defaultTenant = tenants.find((tenant) => tenant.slug === defaultSlug) || tenants[0];
  if (defaultNode) defaultNode.textContent = defaultTenant ? (defaultTenant.short_name || defaultTenant.name || '--') : '--';
