function updateAdminTopEntryLinks() {
  const tenants = ensureAdminTenants();
  const defaultSlug = adminSiteConfig.default_tenant_slug || '';
  const defaultTenant = tenants.find((tenant) => tenant.slug === defaultSlug) || tenants[0];
  const slug = defaultTenant && defaultTenant.slug ? defaultTenant.slug : 'laowang';
  const workbenchLink = document.getElementById('admin-top-workbench-link');
  const h5Link = document.getElementById('admin-top-h5-link');
  if (workbenchLink) workbenchLink.href = `/kol-workbench?tenant=${encodeURIComponent(slug)}`;
  if (h5Link) h5Link.href = `/h5?tenant=${encodeURIComponent(slug)}`;
}

function updateDefaultTenantSlug(value) {
  adminSiteConfig.default_tenant_slug = value || '';
  renderTenantConfigList();
}

function selectAdminTenant(index) {
  const tenants = ensureAdminTenants();
  if (!tenants.length) {
    selectedAdminTenantIndex = 0;
    renderTenantConfigList();
    return;
  }
  selectedAdminTenantIndex = Math.max(0, Math.min(index, tenants.length - 1));
  renderTenantConfigList();
}

function addAdminTenant() {
  const tenants = ensureAdminTenants();
  const nextTenant = buildNewAdminTenant(tenants.length);
  tenants.push(nextTenant);
  if (!adminSiteConfig.default_tenant_slug) {
    adminSiteConfig.default_tenant_slug = nextTenant.slug;
  }
  selectedAdminTenantIndex = tenants.length - 1;
  renderTenantConfigList();
}

function updateAdminTenantField(field, value) {
  const tenants = ensureAdminTenants();
  const tenant = tenants[selectedAdminTenantIndex];
  if (!tenant) return;
  const previousSlug = tenant.slug || '';
  const nextValue = field === 'slug' ? sanitizeTenantSlug(value) : value;
  tenant[field] = nextValue;
  if (field === 'slug' && adminSiteConfig.default_tenant_slug === previousSlug) {
    adminSiteConfig.default_tenant_slug = nextValue;
  }
  renderTenantSidebar();
}

function updateAdminTenantNewsAggregationPrompt(value) {
  const tenants = ensureAdminTenants();
  const tenant = tenants[selectedAdminTenantIndex];
  if (!tenant) return;
  const algorithm = ensureAdminTenantNewsAggregationAlgorithm(tenant);
  algorithm.source_prompt = String(value || '').trim();
  algorithm.rule_plan = {};
  algorithm.rule_atoms = [];
  algorithm.updated_by = 'admin';
  algorithm.updated_at = new Date().toISOString();
  markAdminSiteConfigDirty('新闻聚合规则已修改，保存后将按受控原子重新编译。');
}

function adminNormalizeDashboardMode(mode) {
  return ['market', 'industry', 'signal-stock'].includes(mode) ? mode : 'market';
}

function adminNormalizeDashboardLayout(layout) {
  if (layout === '3x3') return '2x3';
  if (layout === '4x4') return '2x4';
  return ['2x2', '2x3', '2x4', '2x5'].includes(layout) ? layout : '2x2';
}

function adminGetDashboardCardTarget(layout) {
  if (layout === '2x3') return 6;
  if (layout === '2x4') return 8;
  if (layout === '2x5') return 10;
  return 4;
}

function adminGetDashboardSegmentConfig(mode) {
  const configs = {
    market: { title: '市场进攻意愿卡', note: '先回答今天市场是在追逐高弹性方向，还是更偏向防守。', formula: '总分 = 35%广度改善分 + 25%资金回流分 + 25%主线参与分 - 15%防御压力分' },
    industry: { title: '行业景气验证卡', note: '先判断这条主线是基本面继续验证，还是只有情绪热度。', formula: '总分 = 30%订单景气分 + 25%价格景气分 + 20%库存去化分 + 15%政策催化分 + 10%资本开支确认分' },
    'signal-stock': { title: '主线信号个股卡', note: '先判断哪些个股还在验证主线，哪些已经开始掉队。', formula: '总分 = 35%龙头强度分 + 30%业绩兑现分 + 20%资金承接分 + 15%估值安全分' },
  };
  return configs[adminNormalizeDashboardMode(mode)] || configs.market;
}

function adminGetDashboardComponentLibrary(mode) {
  const libraries = {
    market: [
      { id: 'market_breadth', label: '广度改善分', source: '全市场行情库', metric: '上涨/下跌家数、站上MA20占比、新高-新低差', window: '1D', aggregation: '0-100评分', defaultWeight: 0.35 },
      { id: 'northbound_flow', label: '资金回流分', source: '北向/南向资金库', metric: '净流入占成交比、3日累计、连续净流入天数', window: '1D / 3D', aggregation: '0-100评分', defaultWeight: 0.25 },
      { id: 'policy_heat', label: '防御压力分', source: '风格因子库', metric: '银行/红利相对成长超额、低波ETF净流入', window: '1D / 5D', aggregation: '0-100评分', defaultWeight: 0.15 },
    ],
    industry: [
      { id: 'industry_orders', label: '订单景气分', source: '行业指标库', metric: '新增订单同比、在手订单覆盖、开工率', window: '1W / 1M', aggregation: '0-100评分', defaultWeight: 0.3 },
      { id: 'industry_price', label: '价格景气分', source: '产业链价格库', metric: '产品价格指数、价差、提价持续性', window: '1W / 1M', aggregation: '0-100评分', defaultWeight: 0.25 },
      { id: 'industry_inventory', label: '库存去化分', source: '行业库存库', metric: '库存天数、主动/被动补库、去库斜率', window: '1M', aggregation: '0-100评分', defaultWeight: 0.2 },
    ],
    'signal-stock': [
      { id: 'leader_strength', label: '龙头强度分', source: '个股行情库', metric: '相对行业超额收益、回撤控制、成交额排名', window: '5D / 20D', aggregation: '0-100评分', defaultWeight: 0.35 },
      { id: 'valuation_band', label: '估值安全分', source: '估值与财报库', metric: 'PE/PS分位、PEG、相对历史分位', window: '1Q / 3Y', aggregation: '0-100评分', defaultWeight: 0.15 },
      { id: 'earnings_delivery', label: '业绩兑现分', source: '财报与预期库', metric: '营收/利润兑现率、指引上修、订单兑现', window: '1Q', aggregation: '0-100评分', defaultWeight: 0.3 },
    ],
  };
  return JSON.parse(JSON.stringify(libraries[adminNormalizeDashboardMode(mode)] || libraries.market));
}

function adminBuildDefaultDashboardComponents(mode) {
  return adminGetDashboardComponentLibrary(mode).map((item, index) => ({
    id: item.id,
    label: item.label,
    source: item.source,
    metric: item.metric,
    window: item.window,
    aggregation: item.aggregation,
    weight: item.defaultWeight,
    operator: index === 0 ? 'base' : '+',
  }));
}

function adminNormalizeDashboardComponents(components, mode) {
  const library = adminGetDashboardComponentLibrary(mode);
  const libraryMap = Object.fromEntries(library.map(item => [item.id, item]));
  const list = Array.isArray(components) && components.length ? components : adminBuildDefaultDashboardComponents(mode);
  return list.map((item, index) => {
    const raw = item && typeof item === 'object' ? item : {};
    const template = libraryMap[raw.id || raw.componentId] || library[Math.min(index, library.length - 1)];
    return {
      id: template.id,
      label: String(raw.label || template.label || '').trim() || template.label,
      source: String(raw.source || template.source || '').trim() || template.source,
      metric: String(raw.metric || template.metric || '').trim() || template.metric,
      window: String(raw.window || template.window || '').trim() || template.window,
      aggregation: String(raw.aggregation || template.aggregation || '').trim() || template.aggregation,
      weight: Number.isFinite(Number(raw.weight)) ? Number(Number(raw.weight).toFixed(2)) : template.defaultWeight,
      operator: index === 0 ? 'base' : (String(raw.operator || '+').trim() || '+'),
    };
  });
}

function adminBuildDashboardFormula(mode, components, explicitFormula) {
  const formula = String(explicitFormula || '').trim();
  if (formula) return formula;
  const list = Array.isArray(components) ? components : [];
  if (!list.length) return adminGetDashboardSegmentConfig(mode).formula;
  return list.map((item, index) => {
    const prefix = index > 0 && item.operator && item.operator !== 'base' ? ` ${item.operator} ` : '';
    const weightText = Math.abs(Number(item.weight || 1) - 1) < 0.01 ? '' : ` x ${Number(item.weight || 1)}`;
    return `${prefix}${item.label}${weightText}`;
  }).join('');
}

function adminBuildDashboardSources(mode, components, explicitSources) {
  const deduped = [];
  const pushSource = (source) => {
    const text = String(source || '').trim();
    if (text && !deduped.includes(text)) deduped.push(text);
  };
  (Array.isArray(explicitSources) ? explicitSources : []).forEach(pushSource);
  (Array.isArray(components) ? components : []).forEach(item => pushSource(item.source));
  if (!deduped.length) adminGetDashboardComponentLibrary(mode).forEach(item => pushSource(item.source));
  return deduped;
}

function adminBuildDashboardMetricSummaryList(components, limit) {
  const list = Array.isArray(components) ? components : [];
  const maxItems = Number(limit || 2);
  return list.slice(0, maxItems).map((item) => ({
    label: item.label || '组件',
    metric: item.metric || '--',
  }));
}

function adminBuildDashboardMetricCompactText(components, limit) {
  const list = Array.isArray(components) ? components : [];
  if (!list.length) return '点击查看详细指标构成';
  const maxItems = Number(limit || 2);
  const names = list.slice(0, maxItems).map((item) => item.label || '组件');
  const suffix = list.length > maxItems ? `等${list.length}项` : '';
  return `指标：${names.join('、')}${suffix}`;
}

function adminResolveTenantDashboardState(tenant) {
  const state = (tenant && tenant.fund_dashboard_config) || {};
  const published = state.published || {};
  const layout = adminNormalizeDashboardLayout(published.layout || '2x2');
  const cards = Array.from({ length: adminGetDashboardCardTarget(layout) }, (_, index) => {
    const raw = Array.isArray(published.cards) ? published.cards[index] : null;
    const mode = adminNormalizeDashboardMode((raw && (raw.mode || raw.segmentId)) || 'market');
    const components = adminNormalizeDashboardComponents(raw && raw.components, mode);
    return raw ? {
      ...raw,
      mode,
      segmentId: mode,
      components,
      formula: adminBuildDashboardFormula(mode, components, raw.formula),
      sources: adminBuildDashboardSources(mode, components, raw.sources),
    } : {
      mode,
      segmentId: mode,
      name: `${adminGetDashboardSegmentConfig(mode).title} ${index + 1}`,
      value: '--',
      assessment: '当前还没有发布这个格子的具体内容。',
      status: 'attention',
      prompt: '',
      components,
      formula: adminBuildDashboardFormula(mode, components),
      sources: adminBuildDashboardSources(mode, components),
    };
  });
  return {
    layout,
    title: published.title || tenant.dashboard_title || '今日核心指标面板',
    note: published.note || tenant.dashboard_description || '这里只展示当前租户已发布到 H5 基本面的格子。',
    cards,
  };
}

