async function saveHermesSettings() {
  const button = document.getElementById('save-hermes-settings');
  const currentHermesSettings = (adminSiteConfig && adminSiteConfig.hermes_settings) || {};
  let hermesIntentTree = [];
  let hermesRoutePriority = [];
  let hermesTemplateTree = {};
  let hermesChartTypesEnabled = [];
  let hermesInterceptionSkills = [];
  try {
    hermesIntentTree = parseAdminConfigJsonField('hermes-intent-tree', currentHermesSettings.intent_tree || []);
    hermesRoutePriority = parseAdminConfigListField('hermes-route-priority', currentHermesSettings.route_priority || []);
    hermesTemplateTree = parseAdminConfigJsonField('hermes-template-tree', currentHermesSettings.template_tree || {});
    hermesChartTypesEnabled = parseAdminConfigListField('hermes-chart-types-enabled', currentHermesSettings.chart_types_enabled || []);
    hermesInterceptionSkills = parseAdminConfigJsonField('hermes-interception-skills', currentHermesSettings.interception_skills || []);
    if (!Array.isArray(hermesInterceptionSkills)) throw new Error('hermes-interception-skills 必须是 JSON 数组。');
  } catch (error) {
    markAdminSiteConfigDirty((error && error.message) || 'Hermes 配置格式校验失败，请检查后再保存。');
    showToast('Hermes 配置格式有误');
    return;
  }
  if (button) {
    button.disabled = true;
    button.textContent = '保存中...';
  }
  try {
    const res = await fetch('/api/admin/site-config', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        hermes_settings: {
          ...currentHermesSettings,
          interception_skills_enabled: Boolean(document.getElementById('hermes-interception-skills-enabled') && document.getElementById('hermes-interception-skills-enabled').checked),
          interception_skills: hermesInterceptionSkills,
          dav_access_enabled: Boolean(document.getElementById('hermes-dav-access-enabled') && document.getElementById('hermes-dav-access-enabled').checked),
          investor_access_enabled: Boolean(document.getElementById('hermes-investor-access-enabled') && document.getElementById('hermes-investor-access-enabled').checked),
          thinking_process_enabled: Boolean(document.getElementById('hermes-thinking-process-enabled') && document.getElementById('hermes-thinking-process-enabled').checked),
          default_response_style: document.getElementById('hermes-default-response-style')
            ? String(document.getElementById('hermes-default-response-style').value || 'structured').trim() || 'structured'
            : (currentHermesSettings.default_response_style || 'structured'),
          chart_types_enabled: hermesChartTypesEnabled,
          route_priority: hermesRoutePriority,
          intent_tree: hermesIntentTree,
          template_tree: hermesTemplateTree,
        },
      }),
    });
    const data = await res.json();
    if (!res.ok || !data.success) throw new Error((data && data.error) || 'save_failed');
    adminSiteConfig = data.site_config;
    window.SITE_CONFIG = data.site_config;
    renderSiteConfigForm();
    broadcastSiteConfigUpdate();
    markAdminSiteConfigSaved('Hermes 全部能力配置已保存，新的请求会立即按最新配置生效。');
    showToast('Hermes 配置已保存');
  } catch (error) {
    markAdminSiteConfigDirty('Hermes 配置保存失败，请重试。');
    showToast('保存失败');
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = '保存并生效';
    }
  }
}

