async function renderAccessAudit() {
  const res = await fetch('/api/admin/access-stats');
  if (!res.ok) return;
  const data = await res.json();
  const logBody = document.getElementById('audit-log-body');
  const axis = (overrides) => window.GangtiseEcharts.axisBase(Object.assign({
    axisLabel: { color: '#445468', fontSize: 11 },
    splitLine: { lineStyle: { color: 'rgba(47,116,192,0.08)' } },
  }, overrides || {}));
  const grid = (overrides) => window.GangtiseEcharts.gridBase(Object.assign({ top: 24, left: 18, right: 18, bottom: 34 }, overrides || {}));
  ['auditDailyChart', 'auditPathChart', 'auditIpChart'].forEach((id) => window.GangtiseEcharts && window.GangtiseEcharts.dispose(id));
  window.GangtiseEcharts.render('auditDailyChart', {
    color: ['#C8A96E'],
    tooltip: window.GangtiseEcharts.tooltipBase(),
    grid: grid({ bottom: 44 }),
    xAxis: { type: 'category', data: data.daily_counts.map((item) => item.day.slice(5)), ...axis({ splitLine: { show: false } }) },
    yAxis: { type: 'value', ...axis() },
    series: [{ name: '访问量', type: 'line', smooth: true, symbol: 'circle', symbolSize: 6, lineStyle: { width: 2.4, color: '#C8A96E' }, areaStyle: { color: 'rgba(200,169,110,0.12)' }, itemStyle: { color: '#C8A96E' }, data: data.daily_counts.map((item) => item.count) }],
  });
  window.GangtiseEcharts.render('auditPathChart', {
    color: ['#3498DB'],
    tooltip: window.GangtiseEcharts.tooltipBase(),
    grid: grid({ bottom: 18 }),
    xAxis: { type: 'value', ...axis() },
    yAxis: { type: 'category', data: data.top_paths.map((item) => item.path), ...axis({ splitLine: { show: false }, axisLabel: { color: '#182132', fontSize: 11 } }) },
    series: [{ name: '次数', type: 'bar', barWidth: '52%', itemStyle: { color: 'rgba(52,152,219,0.72)', borderRadius: [0, 10, 10, 0] }, data: data.top_paths.map((item) => item.count) }],
  });
  window.GangtiseEcharts.render('auditIpChart', {
    color: ['#2ECC71'],
    tooltip: window.GangtiseEcharts.tooltipBase(),
    grid: grid({ bottom: 18 }),
    xAxis: { type: 'value', ...axis() },
    yAxis: { type: 'category', data: data.top_ips.map((item) => item.ip), ...axis({ splitLine: { show: false }, axisLabel: { color: '#182132', fontSize: 11 } }) },
    series: [{ name: '次数', type: 'bar', barWidth: '52%', itemStyle: { color: 'rgba(46,204,113,0.72)', borderRadius: [0, 10, 10, 0] }, data: data.top_ips.map((item) => item.count) }],
  });
  if (logBody) {
    logBody.innerHTML = data.recent_logs.map(r => `<tr><td>${r.created_at}</td><td>${r.ip}</td><td>${r.path}</td><td>${r.method}</td><td>${r.status_code}</td></tr>`).join('');
  }
}

