  li.innerHTML = `<input type="time" style="width:76px;background:#0D1B2A;border:1px solid rgba(200,169,110,0.15);color:#C8A96E;padding:6px;border-radius:4px;font-size:12px;outline:none;flex-shrink:0"><input type="text" placeholder="议程内容" style="flex:1;background:#0D1B2A;border:1px solid rgba(200,169,110,0.15);color:#F8F6F0;padding:6px 10px;border-radius:4px;font-size:12px;outline:none"><button onclick="this.closest('.ev-agenda-item').remove()" style="background:transparent;border:none;color:#9A9590;cursor:pointer;font-size:14px;padding:4px">✕</button>`;
